-- Account security: self-service password reset, admin account actions, login tracking.
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "last_login_at" TIMESTAMP WITHOUT TIME ZONE;
-- Set when an admin issues a temporary password; cleared when the user picks their own.
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "must_change_password" BOOLEAN NOT NULL DEFAULT FALSE;

CREATE TABLE IF NOT EXISTS "password_reset_tokens" (
    "token_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" NUMERIC NOT NULL REFERENCES "users" ("user_id") ON DELETE CASCADE,
    -- SHA-256 of the emailed token; the token itself is never stored.
    "token_hash" CHAR(64) NOT NULL UNIQUE,
    "expires_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "used_at" TIMESTAMP WITHOUT TIME ZONE,
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "ix_password_reset_tokens_user" ON "password_reset_tokens" ("user_id");

-- Admin actions on accounts other than role changes (those stay in user_role_history).
CREATE TABLE IF NOT EXISTS "user_account_events" (
    "event_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "target_user_id" NUMERIC NOT NULL REFERENCES "users" ("user_id") ON DELETE CASCADE,
    "event_type" VARCHAR(40) NOT NULL
        CHECK ("event_type" IN ('CREATED', 'LOCKED', 'UNLOCKED', 'PASSWORD_RESET_BY_ADMIN', 'PASSWORD_RESET_BY_EMAIL')),
    "note" VARCHAR(500),
    "actor_user_id" NUMERIC REFERENCES "users" ("user_id") ON DELETE SET NULL,
    "actor_email" VARCHAR(254),
    "created_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "ix_user_account_events_target" ON "user_account_events" ("target_user_id", "created_at" DESC);
